function sanitize(value) {
  const secret = ['access_token','refresh_token','client_secret','authorization','apikey','api_key','secret','password'];
  if (Array.isArray(value)) return value.map(sanitize);
  if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([k,v]) => [k, secret.includes(k.toLowerCase()) ? '[REDACTED]' : sanitize(v)]));
  return value;
}
